                if isinstance(s, dict)
            ]
        return out

    def _emit(self, result) -> Data:
        return Data(value=json.dumps(result, ensure_ascii=False))

    # ---- tool ------------------------------------------------------------

    def updateTask(self) -> Data:
        task_id = self._txt(self.task_id)
        if not task_id:
            return self._emit({"ok": False, "error": "missing_task_id",
                               "message": "task_id is required."})

        body = {}
        title = self._txt(self.title)
        if title:
            body["title"] = title
        domain = self._txt(self.domain)
        if domain in ("health", "home", "car", "finance", "family", "pets"):
            body["domain"] = domain
        priority = self._txt(self.priority)
        if priority in ("low", "normal", "high", "urgent"):
            body["priority"] = priority
        status = self._txt(self.new_status)
        if status in ("open", "done", "snoozed"):
            body["status"] = status

        # 'null' is how a text-only tool surface expresses "clear this field".
        for field, raw in (("dueAt", self.due_at),
                           ("notes", self.notes),
                           ("snoozedUntil", self.snoozed_until)):
            value = self._txt(raw)
            if value is None:
                continue
            body[field] = None if value.lower() == "null" else value

        tags_raw = self._txt(self.tags)
        if tags_raw is not None:
            body["tags"] = [] if tags_raw.lower() == "null" else (self._list(tags_raw) or [])[:20]

        if not body:
            return self._emit({"ok": False, "error": "nothing_to_update",
                               "message": "No fields supplied. Send at least one change."})

        result = self._call("PATCH", "/me/tasks/" + task_id, body=body)
        if not result.get("ok"):
            return self._emit(result)
        return self._emit({"ok": True, "task": self._slim(result.get("task"))})

