                        continue
                    label = (entry.get("label") or "").strip()
                    if not label:
                        continue
                    option = {"label": label[:80]}
                    for field in ("dueAt", "title", "notes"):
                        value = entry.get(field)
                        if isinstance(value, str) and value.strip():
                            option[field] = value.strip()
                    options.append(option)

        # Best guess, in priority order: explicit guess, else the first option's date.
        guess = self._txt(self.due_at_guess)
        if not guess and options:
            guess = options[0].get("dueAt")

        # ALWAYS create the task. A held item is a real matter with a question attached,
        # never a withheld one. 'high' cost -> kind 'list' so the guess cannot fire.
        task_body = {"title": title, "domain": domain, "priority": priority}
        task_body["kind"] = "reminder" if (guess and cost == "low") else "list"
        if guess:
            task_body["dueAt"] = guess
        tags = self._list(self.tags)
        if tags:
            task_body["tags"] = tags[:20]
        notes = self._txt(self.notes)
        if notes:
            task_body["notes"] = notes

        created = self._call("POST", "/me/tasks", body=task_body)
        if not created.get("ok"):
            return self._emit(created)
        task = created.get("task") or {}

        # The backend exposes no endpoint for CREATING a clarification, so the row is
        # handed back in the flow's structured output for the caller to persist and
        # link by taskId. See PLANNING-AGENT.md, "The clarification write gap".
        clarification = {
            "taskId": task.get("id"),
            "question": question[:300],
            "kind": kind,
            "costOfWrong": cost,
            "options": options,
            "sourceText": self._txt(self.source_text),
            "draft": {
                "title": title,
                "domain": domain,
                "priority": priority,
                "tags": tags or [],
                "notes": notes,
                "dueAt": guess,
            },
        }
        return self._emit({"ok": True, "task": self._slim(task),
                           "clarification": clarification})
